// === CONTEXT MANAGER ===
// Gerencia historico conversacional por subscriber com janela deslizante
// v2.1: aplica workshop_config vars no prompt final (cobre campaign_data + cliente_contexto + sub-blocos)

const input = $('Execute Workflow Trigger').first().json;
const config = $('Configuracao do Agente').first().json;

// Substitui placeholders {{var}} baseado em workshop_config (passado pelo Configuracao do Agente)
function applyWorkshopVars(prompt, ws) {
  if (!ws) return prompt;
  return prompt
    .replace(/\{\{data_full_text\}\}/g, ws.data_full_text)
    .replace(/\{\{data_short_text\}\}/g, ws.data_short_text)
    .replace(/\{\{data_event_range\}\}/g, ws.data_event_range)
    .replace(/\{\{data_template_var\}\}/g, ws.data_template_var)
    .replace(/\{\{event_time_start\}\}/g, ws.event_time_start)
    .replace(/\{\{event_time_end\}\}/g, ws.event_time_end)
    .replace(/\{\{duracao\}\}/g, ws.duracao)
    .replace(/\{\{end_signup_text\}\}/g, ws.end_signup_text);
}

const subscriber_id = input.subscriber_id;
const mensagem = input.mensagem;
const nome = input.nome || 'Lead';
const contexto_inicial = input.contexto_inicial || '';
const cliente_contexto = input.cliente_contexto || '';
const agent_id = config.agent_id || input.agent_id || 'bia';
const conv_key = subscriber_id + '_' + agent_id;

// === SUPABASE CONTEXT (via HTTP Request node upstream) ===
let messages = [];
try {
  const sbData = $('Read Supabase Context').first().json;
  if (sbData && Array.isArray(sbData.messages) && sbData.messages.length > 0) {
    messages = [...sbData.messages];
  }
} catch (sbReadErr) {
  console.error('[SUPABASE READ ERROR]', conv_key, sbReadErr.message || sbReadErr);
}

// Injeta contexto_inicial na primeira interacao (se fornecido e historico vazio)
if (contexto_inicial && messages.length === 0) {
  messages.push({
    role: 'user',
    content: '[CONTEXTO] O lead recebeu a seguinte mensagem antes de responder: ' + contexto_inicial,
    timestamp: new Date().toISOString()
  });
}

// Adiciona mensagem do usuario
messages.push({
  role: 'user',
  content: mensagem,
  timestamp: new Date().toISOString()
});

// Janela deslizante: mantem apenas as ultimas N mensagens
if (messages.length > config.context_window) {
  messages = messages.slice(-config.context_window);
}

// === CAMPAIGN DATA INJECTION — Supabase only, zero fallback ===
let campaign_injected = '';
let campaignData = '';
try {
  const campaignResponse = $('Read Campaign Data').first().json;
  if (typeof campaignResponse === 'string' && campaignResponse.length > 10) {
    campaignData = campaignResponse;
  }
} catch (e) {
  console.error('[CAMPAIGN READ ERROR]', e.message || e);
}
if (campaignData) {
  campaign_injected = '<campanha>\n' + campaignData + '\n</campanha>';
}

// === KNOWLEDGE BASE INJECTION (Q&A entries) ===
// KB via staticData removido — zero staticData neste workflow
// Se precisar KB no futuro, implementar via Supabase RPC
const kbEntries = [];

let kb_injected_qa = '';

if (kbEntries.length > 0) {
  const stopwords = new Set(['a','o','e','de','do','da','em','um','uma','que','para','com','nao','se','os','as','por','mais','no','na','eu','ele','ela','voce','nos','ao','ou','tem','ter','ser','foi','sao','como','mas','ate','ja','seu','sua','isso','esta','esse','essa','quando','muito','tambem','qual','das','dos','pela','pelo','ha','era','meu','minha','cada','onde','sobre','entre','apos','sem','mesmo','pode','faz','vou','vai','estou','tudo','oi','ola','bom','boa','dia','noite','tarde','obrigado','obrigada']);

  const msgWords = mensagem.toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .split(/\s+/)
    .filter(w => w.length > 2 && !stopwords.has(w));

  const scored = kbEntries.map(entry => {
    const entryWords = entry.pergunta.toLowerCase()
      .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
      .split(/\s+/)
      .filter(w => w.length > 2 && !stopwords.has(w));
    const overlap = msgWords.filter(w => entryWords.some(ew => ew.includes(w) || w.includes(ew))).length;
    return { entry, score: overlap };
  }).filter(s => s.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, 10);

  if (scored.length > 0) {
    let kbText = '<campanha>\nDados da campanha atual e base de conhecimento:\n\n';
    let totalChars = kbText.length;
    const MAX_KB_CHARS = 6000;

    for (const { entry } of scored) {
      const entryText = 'P: ' + entry.pergunta + '\nR: ' + entry.resposta + '\n\n';
      if (totalChars + entryText.length > MAX_KB_CHARS) break;
      kbText += entryText;
      totalChars += entryText.length;
    }

    kbText += '</campanha>';
    kb_injected_qa = kbText;
  }
}

let finalPrompt = config.prompt;
if (campaign_injected) {
  finalPrompt += '\n\n' + campaign_injected;
}
if (cliente_contexto && cliente_contexto !== 'LEAD_NOVO') {
  finalPrompt += '\n\n<cliente>\nPERFIL DO LEAD (dados reais \u2014 use pra personalizar a conversa):\n' + cliente_contexto + '\n\nCOMO USAR ESSE PERFIL:\n\nRECONHECIMENTO:\n- Se tem COMPRAS ou EVENTOS: trate como algu\u00e9m da casa. "Que bom te ver de novo!" ou "Voc\u00ea j\u00e1 conhece o trabalho do {{NOME_EXPERT}}, n\u00e9?"\n- Se tem NICHO/FATURAMENTO: use pra personalizar. "Da \u00faltima vez que tivemos contato, vi que voc\u00ea tava no [nicho] com [momento]. Como t\u00e3o as coisas?"\n- Se fez MENTORIA: \u00e9 VIP. Trate com proximidade especial.\n- Se tem CHECKPOINT com faturamento: refer\u00eancia sutil. "Voc\u00ea j\u00e1 tava num momento legal no neg\u00f3cio... evoluiu desde ent\u00e3o?"\n\nCONTEXTUALIZA\u00c7\u00c3O:\n- Conecte o passado com o presente: "Voc\u00ea j\u00e1 participou do [evento]. Esse workshop \u00e9 o pr\u00f3ximo passo natural."\n- Use o nicho pra dar exemplos espec\u00edficos: "Pra quem \u00e9 de [nicho], a parte de [X] do workshop vai fazer muito sentido."\n- Se saiu de mentoria: cuidado e carinho. N\u00e3o force. Pergunte como est\u00e1.\n\nREGRAS:\n- NUNCA diga "vi no sistema" ou "segundo nossos registros". Fale como quem lembra naturalmente.\n- NUNCA mencione dados sens\u00edveis (CPF, email, valores exatos de compra).\n- Se o perfil mostra LEAD sem hist\u00f3rico: siga o fluxo normal, ignore esta se\u00e7\u00e3o.\n- M\u00e1ximo 1-2 refer\u00eancias ao hist\u00f3rico por conversa. N\u00e3o despeje tudo de uma vez.\n</cliente>';
}

if (kb_injected_qa) {
  finalPrompt += '\n\n' + kb_injected_qa;
}

// === APLICA workshop_config vars NO PROMPT FINAL (cobre tudo: L1+L2+L3+campaign+cliente+kb+sub-blocos) ===
if (config._workshop) {
  finalPrompt = applyWorkshopVars(finalPrompt, config._workshop);
}
// Sanity check: detectar placeholder nao substituido
const _placeholderResidual = finalPrompt.match(/\{\{[a-z_]+\}\}/);
if (_placeholderResidual) {
  console.error('[CONTEXT-MGR] PLACEHOLDER NAO SUBSTITUIDO no prompt final: ' + _placeholderResidual[0]);
}

const apiMessages = messages.map(m => ({
  role: m.role,
  content: m.content
}));

  if (agent_id === 'bia-recovery') {
    finalPrompt += '\n\n<recovery>\nEste lead ABANDONOU O CHECKOUT do workshop.\nEle recebeu um template de recovery com video do {{NOME_EXPERT}} e botao "Qual \u00e9 o cupom, Bia?".\nEle clicou o botao \u2014 essa \u00e9 a primeira interacao dele.\n\nIMPORTANTE:\n- Ele ja demonstrou interesse (foi ate o checkout)\n- Ele clicou o botao \u2014 esta curioso, aberto a conversar\n- Nao sabe que tem desconto \u2014 vai descobrir pela Bia\n- Siga o MODO ESPECIAL do seu prompt (L3) pra esse lead\n</recovery>';
  }

  if (contexto_inicial === 'boas_vindas_compra') {
    finalPrompt += '\n\n<boas_vindas>\nEste lead ACABOU DE COMPRAR o workshop.\nEle recebeu um template de boas-vindas com video do {{NOME_EXPERT}} e respondeu.\n\nIMPORTANTE:\n- Celebre a compra genuinamente\n- Ele ja esta dentro \u2014 nao precisa convencer de nada\n- Foque em experiencia, nao em venda\n- Responda duvidas com carinho e precisao\n- Se nao souber algo de logistica, use [HANDOFF_HUMANO]\n- Upsell de gravacao/apostila SO se surgir naturalmente\n- GARANTA que o lead esteja no grupo do WhatsApp \u2014 o link da transmissao ao vivo sera enviado por la no DIA DO EVENTO. NAO existe link antecipado\n</boas_vindas>';
  }

return [{
  json: {
    subscriber_id,
    nome,
    mensagem,
    tipo_original: input.tipo_original || 'texto',
    start_time: Date.now(),
    api_messages: apiMessages,
    system_prompt: finalPrompt,
    provider: config.provider,
    model: config.model,
    temperature: config.temperature,
    max_tokens: config.max_tokens,
    total_context_messages: apiMessages.length,
    contexto_inicial,
    agent_id,
    kb_entries_injected: kb_injected_qa ? true : false
  }
}];

// === NORMALIZE LLM RESPONSE ===
// Handles both OpenAI and Claude response formats
// Detects errors and triggers fallback if needed

const config = $('Configuracao do Agente').first().json;
const contextData = $('Context Manager').first().json;
const response = $input.first().json;
const provider = contextData.provider;

let resposta = '';
let tokens_in = 0;
let tokens_out = 0;
let llm_provider = provider;
let llm_model = contextData.model;
let has_error = false;
let error_detail = '';

try {
  if (provider === 'anthropic') {
    // Claude Messages API format
    if (response.content && response.content[0]) {
      resposta = response.content[0].text || '';
      tokens_in = response.usage?.input_tokens || 0;
      tokens_out = response.usage?.output_tokens || 0;
      llm_model = response.model || contextData.model;
    } else if (response.error) {
      has_error = true;
      error_detail = response.error.message || JSON.stringify(response.error);
    } else {
      has_error = true;
      error_detail = 'Claude response format unexpected: ' + JSON.stringify(response).substring(0, 200);
    }
  } else {
    // OpenAI format
    if (response.choices && response.choices[0]) {
      resposta = response.choices[0].message.content || '';
      tokens_in = response.usage?.prompt_tokens || 0;
      tokens_out = response.usage?.completion_tokens || 0;
      llm_model = response.model || contextData.model;
    } else if (response.error) {
      has_error = true;
      error_detail = response.error.message || JSON.stringify(response.error);
    } else {
      has_error = true;
      error_detail = 'OpenAI response format unexpected: ' + JSON.stringify(response).substring(0, 200);
    }
  }
} catch (e) {
  has_error = true;
  error_detail = e.message;
}

// Filtro de erro: verifica se resposta contem keywords de erro
if (!has_error && resposta) {
  const respostaLower = resposta.toLowerCase();
  const isErrorContent = config.error_keywords.some(kw => respostaLower.includes(kw.toLowerCase()));
  if (isErrorContent || !resposta.trim()) {
    resposta = config.error_response;
  }
}

// Determine fallback info
const fallback_provider = provider === 'openai' ? config.fallback_provider : 'openai';
const fallback_model = config.fallback_model;

return [{
  json: {
    subscriber_id: contextData.subscriber_id,
    nome: contextData.nome,
    resposta,
    has_error,
    error_detail,
    needs_fallback: has_error && !!fallback_provider,
    fallback_provider,
    fallback_model,
    handoff: false,
    llm_provider,
    llm_model,
    tokens_in,
    tokens_out,
    context_messages: contextData.total_context_messages,
    // Pass through for fallback
    system_prompt: contextData.system_prompt,
    api_messages: contextData.api_messages,
    temperature: contextData.temperature,
    max_tokens: contextData.max_tokens,
    // Observability (Story 4.7)
    tipo_original: contextData.tipo_original || 'texto',
    start_time: contextData.start_time || Date.now(),
    agent_id: contextData.agent_id || 'bia'
  }
}];

// === PROCESSA FALLBACK ===
// BUG-018: Output supabase_messages pra Save node downstream
const config = $('Configuracao do Agente').first().json;
const normalizeData = $('Normalize Response').first().json;
const triggerInput = $('Execute Workflow Trigger').first().json;
const response = $input.first().json;
const fallbackProvider = normalizeData.fallback_provider;

let resposta = '';
let tokens_in = 0;
let tokens_out = 0;
let llm_model = normalizeData.fallback_model;

try {
  if (fallbackProvider === 'anthropic') {
    resposta = response.content?.[0]?.text || '';
    tokens_in = response.usage?.input_tokens || 0;
    tokens_out = response.usage?.output_tokens || 0;
    llm_model = response.model || llm_model;
  } else {
    resposta = response.choices?.[0]?.message?.content || '';
    tokens_in = response.usage?.prompt_tokens || 0;
    tokens_out = response.usage?.completion_tokens || 0;
    llm_model = response.model || llm_model;
  }
} catch (e) {
  resposta = config.error_response;
}

if (!resposta || !resposta.trim()) {
  resposta = config.error_response;
}

// Salva no contexto
const staticData = $getWorkflowStaticData('global');
const sid = normalizeData.subscriber_id;
const agent_id = normalizeData.agent_id || 'bia';
const conv_key = sid + '_' + agent_id;
if (staticData.conversations && staticData.conversations[conv_key]) {
  staticData.conversations[conv_key].messages.push({
    role: 'assistant', content: resposta, timestamp: new Date().toISOString()
  });
}

// Mensagens completas pra Supabase write
const supabase_messages = (staticData.conversations && staticData.conversations[conv_key])
  ? staticData.conversations[conv_key].messages
  : [{ role: 'assistant', content: resposta, timestamp: new Date().toISOString() }];

const respostaLower = resposta.toLowerCase();
const handoff_phrases = config.handoff_keywords.map(k => k.toLowerCase());
const is_handoff = handoff_phrases.some(phrase => respostaLower.includes(phrase));

return [{
  json: {
    subscriber_id: sid,
    nome: normalizeData.nome,
    resposta,
    handoff: is_handoff,
    llm_provider: fallbackProvider,
    llm_model,
    tokens_in,
    tokens_out,
    was_fallback: true,
    context_messages: normalizeData.context_messages,
    tipo_original: normalizeData.tipo_original || 'texto',
    start_time: normalizeData.start_time || Date.now(),
    error_detail: normalizeData.error_detail || '',
    agent_id,
    mensagem: triggerInput.mensagem || '',
    mensagem_original: triggerInput.mensagem || '',
    supabase_subscriber_id: String(sid),
    supabase_agent_id: agent_id,
    supabase_messages,
    chatwoot_conversation_id: triggerInput.chatwoot_conversation_id || null,
    chatwoot_contact_id: triggerInput.chatwoot_contact_id || null,
    phone: triggerInput.phone || sid
  }
}];

// === FINALIZA RESPOSTA ===
// Salva resposta no contexto e detecta handoff
// BUG-018: Output supabase_messages pra Save node downstream
const data = $input.first().json;
const config = $('Configuracao do Agente').first().json;
const staticData = $getWorkflowStaticData('global');
const triggerInput = $('Execute Workflow Trigger').first().json;

const subscriber_id = data.subscriber_id;
const nome = data.nome;
const respostaRaw = data.resposta;
// Sanitiza markdown: strip **bold** e *italic* que o modelo insiste em usar
const resposta = respostaRaw.replace(/\*\*(.+?)\*\*/g, '$1').replace(/(?<![a-zA-Z0-9])\*(.+?)\*(?![a-zA-Z0-9])/g, '$1').replace(/(?<![a-zA-Z0-9])_(.+?)_(?![a-zA-Z0-9])/g, '$1');
const llm_provider = data.llm_provider;
const llm_model = data.llm_model;
const tokens_in = data.tokens_in;
const tokens_out = data.tokens_out;
const context_messages = data.context_messages;
const contexto_inicial = data.contexto_inicial || '';
const agent_id = data.agent_id || 'bia';
const conv_key = subscriber_id + '_' + agent_id;

// Salva resposta do assistant no contexto
if (staticData.conversations && staticData.conversations[conv_key]) {
  staticData.conversations[conv_key].messages.push({
    role: 'assistant',
    content: resposta,
    timestamp: new Date().toISOString()
  });
}

const respostaLower = resposta.toLowerCase();
const handoff_phrases = config.handoff_keywords.map(k => k.toLowerCase());
const is_handoff = handoff_phrases.some(phrase => respostaLower.includes(phrase));

const tipo_original = data.tipo_original || 'texto';
const latencia_ms = Date.now() - (data.start_time || Date.now());

// Mensagens completas pra Supabase write (inclui resposta do assistant)
const supabase_messages = (staticData.conversations && staticData.conversations[conv_key])
  ? staticData.conversations[conv_key].messages
  : [{ role: 'assistant', content: resposta, timestamp: new Date().toISOString() }];

return [{
  json: {
    subscriber_id,
    nome,
    resposta,
    handoff: is_handoff,
    llm_provider,
    llm_model,
    tokens_in,
    tokens_out,
    was_fallback: false,
    context_messages,
    tipo_original,
    latencia_ms,
    error_detail: data.error_detail || '',
    contexto_inicial,
    agent_id,
    mensagem: triggerInput.mensagem || '',
    mensagem_original: triggerInput.mensagem || '',
    supabase_subscriber_id: String(subscriber_id),
    supabase_agent_id: agent_id,
    supabase_messages,
    chatwoot_conversation_id: triggerInput.chatwoot_conversation_id || null,
    chatwoot_contact_id: triggerInput.chatwoot_contact_id || null,
    phone: triggerInput.phone || subscriber_id
  }
}];

// === HANDOFF ACTIONS — Cloud API Edition ===
// Pipeline Cloud API pura:
// 1. Supabase: is_human_takeover = true
// 2. Chatwoot: conversa status = open
// 3. SMS + WhatsApp pro suporte via Twilio

const https = require('https');

function httpRequest(method, hostname, path, headers, body) {
  return new Promise((resolve, reject) => {
    const bodyStr = body ? (typeof body === 'string' ? body : JSON.stringify(body)) : '';
    const reqHeaders = { ...headers };
    if (body) reqHeaders['Content-Length'] = Buffer.byteLength(bodyStr);
    const options = { hostname, path, method, headers: reqHeaders, timeout: 10000 };
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve({ status: res.statusCode, data: JSON.parse(data) }); }
        catch { resolve({ status: res.statusCode, data: { raw: data } }); }
      });
    });
    req.on('timeout', () => { req.destroy(); reject({ code: 'ETIMEDOUT' }); });
    req.on('error', (e) => resolve({ status: 0, data: { error: e.message } }));
    if (body) req.write(bodyStr);
    req.end();
  });
}

function httpPostForm(hostname, path, authHeader, formParams) {
  return new Promise((resolve, reject) => {
    const bodyStr = Object.entries(formParams)
      .map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v))
      .join('&');
    const options = {
      hostname, path, method: 'POST',
      headers: {
        'Authorization': authHeader,
        'Content-Type': 'application/x-www-form-urlencoded',
        'Content-Length': Buffer.byteLength(bodyStr)
      }
    };
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve({ status: res.statusCode, data: JSON.parse(data) }); }
        catch { resolve({ status: res.statusCode, data: { raw: data } }); }
      });
    });
    req.on('error', (e) => resolve({ status: 0, data: { error: e.message } }));
    req.write(bodyStr);
    req.end();
  });
}

const input = $input.first().json;
const phone = input.phone;
const nome = input.nome;
let mensagem = 'N/A';
try { mensagem = $('Context Manager').first().json.mensagem || 'N/A'; } catch (e) {}
const resposta_bia = input.resposta || 'N/A';

// Supabase config
const SUPA_HOST = '{{SUPABASE_PROJECT_REF}}.supabase.co';
const SUPA_KEY = '{{SUPABASE_SERVICE_ROLE_KEY}}';

// Chatwoot config
const CHATWOOT_HOST = 'chatwoot.{{SEU_DOMINIO}}';
const CHATWOOT_TOKEN = '{{CHATWOOT_TOKEN}}';
const chatwoot_conversation_id = input.chatwoot_conversation_id;

// Twilio config
const TWILIO_SID = '{{TWILIO_ACCOUNT_SID}}';
const TWILIO_TOKEN = '{{TWILIO_AUTH_TOKEN}}';
const TWILIO_AUTH = 'Basic ' + Buffer.from(TWILIO_SID + ':' + TWILIO_TOKEN).toString('base64');
const TWILIO_FROM = '{{TWILIO_FROM_NUMBER}}';
const SUPORTE_ALERTA = '+{{WHATSAPP_SUPORTE}}';

const notifMsg = 'HANDOFF [Cloud API]: Lead ' + (nome || phone) + '\nMsg: ' + mensagem + '\nBia: ' + resposta_bia.substring(0, 200);

// Execute all in parallel
const results = await Promise.allSettled([
  // 1. Supabase: flag is_human_takeover
  httpRequest('PATCH', SUPA_HOST,
    '/rest/v1/bia_whatsapp_contacts?phone=eq.' + encodeURIComponent(phone),
    {
      'Content-Type': 'application/json',
      'apikey': SUPA_KEY,
      'Authorization': 'Bearer ' + SUPA_KEY,
      'Prefer': 'return=minimal'
    },
    { is_human_takeover: true }
  ),
  // 2. Chatwoot: abrir conversa
  chatwoot_conversation_id
    ? httpRequest('POST', CHATWOOT_HOST,
        '/api/v1/accounts/2/conversations/' + chatwoot_conversation_id + '/toggle_status',
        { 'api_access_token': CHATWOOT_TOKEN, 'Content-Type': 'application/json' },
        { status: 'open' }
      )
    : Promise.resolve({ status: 0, data: { skipped: 'no_conversation_id' } }),
  // 3. SMS alerta
  httpPostForm('api.twilio.com',
    '/2010-04-01/Accounts/' + TWILIO_SID + '/Messages.json',
    TWILIO_AUTH,
    { From: TWILIO_FROM, To: SUPORTE_ALERTA, Body: notifMsg }
  ),
  // 4. WhatsApp suporte
  httpPostForm('api.twilio.com',
    '/2010-04-01/Accounts/' + TWILIO_SID + '/Messages.json',
    TWILIO_AUTH,
    { From: 'whatsapp:' + TWILIO_FROM, To: 'whatsapp:' + SUPORTE_ALERTA, Body: notifMsg }
  )
]);

const supaResult = results[0].status === 'fulfilled' ? results[0].value : { status: 0 };
const cwResult = results[1].status === 'fulfilled' ? results[1].value : { status: 0 };
const smsResult = results[2].status === 'fulfilled' ? results[2].value : { status: 0 };
const waResult = results[3].status === 'fulfilled' ? results[3].value : { status: 0 };

return [{
  json: {
    ...input,
    handoff_actions: {
      supabase_flag: { status: supaResult.status, success: supaResult.status >= 200 && supaResult.status < 300 },
      chatwoot_open: { status: cwResult.status, success: cwResult.status >= 200 && cwResult.status < 300 },
      sms_alerta: { status: smsResult.status, success: smsResult.status >= 200 && smsResult.status < 300 },
      whatsapp_alerta: { status: waResult.status, success: waResult.status >= 200 && waResult.status < 300 }
    }
  }
}];
